import taf.ue.android.data_transfer.utils.data_transfer_utils as dt_utils
from taf.ue.android.exceptions import MultipleNetworkInterfacesFound, NetworkInterfaceNotFound, NoIpError


class IpAddressSelector:

    @staticmethod
    def select_net_interface_ip(network_interfaces_info, network_setting, ip_version, logger):
        ip_addresses = IpAddressSelector.select_net_interface_by_attribute_or_take_available(
            network_interfaces_info, network_setting, logger)
        return IpAddressSelector.select_ip_by_version(ip_addresses, ip_version, logger)

    @staticmethod
    def select_net_interface_by_attribute_or_take_available(network_interfaces_info, network_setting, logger):
        """
        Selects network interface by name or related apn and returns it's ip addresses from network_interfaces_info
        or returns ip addresses of the first available network interface if network_setting is not given
        :param network_interfaces_info: dict {"apn/interface_name": [network_interface_ip_addresses]}
                                        see AndroidDevice.get_all_ips() in .access.android for details
        :param network_setting: network interface unique attribute - interface name or related apn name
        :param logger: just a logger
        :return: a list of ip addresses

        """
        if network_setting:
            return IpAddressSelector.select_net_interface_by_attribute(network_interfaces_info, network_setting, logger)
        else:
            return IpAddressSelector.select_available_net_interface(network_interfaces_info, logger)

    @staticmethod
    def select_ip_by_version(ip_addresses, ip_version, logger):
        """
        Selects a first available ip address in needed ip_version from ip_addresses list
        using trivial check: if `:` in ip address than ip version is 6, else 4
        :param ip_addresses: a list of ip addresses
        :param ip_version: ip version to select, 4 or 6
        :param logger: just a logger

        :raises IncorrectIpVersion: if ip_version is not 4 or 6
        :raises NoIpError: if there is no ip address in ip_addresses list in needed version

        :return: str, ip address in needed version
        """
        dt_utils.check_ip_version(ip_version)
        for address in ip_addresses:
            if dt_utils.get_ip_version(address) == ip_version:
                logger.debug(f'Selected IPv{ip_version} address: {address}')
                return address
        raise NoIpError(f"Chosen network interface has no IPv{ip_version} address: {ip_addresses}")

    @staticmethod
    def select_net_interface_by_attribute(network_interfaces_info, network_setting, logger):
        """
        Select network interface on UE by network interface name (e.g. `rmnet_data0`)
        or related apn name (e.g. `internet`, `ap1.wroc`, `nokia.apn`)

        :raises NetworkInterfaceNotFound: if there is no network interface discovered with given name or apn

        :return: a list of ip addresses
        """
        logger.debug(f'Selecting network interface: network_setting={network_setting}')
        net_setting_ok = "/" not in str(network_setting)
        if not net_setting_ok:
            logger.warning(f'Network setting used for `Start Data Transfer` contains `/` ({network_setting}),'
                           'please use only network interface name or related apn name in further tests. '
                           'In this case will be tried to compare whole interface path with network setting.')

        for net_agent_id, ip_addrs in network_interfaces_info.items():
            net_agent_vals = str(net_agent_id).split("/") if "/" in net_agent_id and net_setting_ok else net_agent_id
            if network_setting in net_agent_vals:
                return ip_addrs
        raise NetworkInterfaceNotFound(f'Network interface with name `{network_setting}` was not found.'
                                       'Make sure that `<iperf|ping>_interface_name` is set correctly. '
                                       f'Available interfaces:\n{network_interfaces_info}')

    @staticmethod
    def select_available_net_interface(network_interfaces_info, logger):
        """
        Return ip addresses of single available network interface from network_interfaces_info

        :raises NoIpError: if no network interface is available
        :raises MultipleNetworkInterfacesFound: if there are more than one network interface available (user should
                                                specify which of them should be used by setting `network_setting`)

        :return: a list of ip addresses
        """
        if len(network_interfaces_info) > 1:
            raise MultipleNetworkInterfacesFound(
                'Multiple network interfaces, but `apn` or `interface_name` parameters are not set. '
                f'Please choose your interface and set one of these identifiers: {network_interfaces_info}')
        else:
            try:
                net_agent_id, interface_ips = next(iter(network_interfaces_info.items()))
            except StopIteration:
                raise NoIpError(f'None interface available on UE:\nnetwork_interfaces_info={network_interfaces_info.items()}\n'
                                'Make sure that UE has assigned ip and interface.')
            logger.debug(f'<iperf|ping>_interface_name is not set, selecting first available interface: {net_agent_id}')
            return interface_ips
